def receipt_materials_cover(receipt, artifact_path, artifact_sha, config_path, config_sha):
    """Verify the cached receipt's full chain per the runbook: the materials manifest file
    hashes to the signed materials_sha256, and its entries cover the CURRENT package and
    deployment configuration digests. A receipt that only matches the package digest does
    not attest the current configuration."""
    statement = receipt.get("signed_statement", {})
    try:
        materials_bytes = (ROOT / receipt["materials_path"]).read_bytes()
        manifest = json.loads(materials_bytes)
    except (KeyError, OSError, ValueError):
        return False, "materials manifest missing or unreadable"
    if hashlib.sha256(materials_bytes).hexdigest() != statement.get("materials_sha256"):
        return False, "materials file digest does not match signed materials_sha256"
    digests = {m.get("path"): m.get("sha256") for m in manifest.get("materials", [])}
    if digests.get(artifact_path) != artifact_sha:
        return False, "materials do not match the current package digest"
    if digests.get(config_path) != config_sha:
        return False, "materials do not cover the current configuration (%s)" % config_path
    return True, "materials cover the current package and configuration""}
